<?php
require __DIR__.'/bootstrap.php';csrf_check();if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($action==='remove')unset($_SESSION['cart'][$id]);elseif($action==='update'){foreach(($_POST['qty']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=max(0,(int)$qty);$q=$pdo->prepare('SELECT stock,active FROM products WHERE id=?');$q->execute([$pid]);$row=$q->fetch();if(!$row||!$row['active']||$qty===0)unset($_SESSION['cart'][$pid]);else $_SESSION['cart'][$pid]=min($qty,(int)$row['stock']);}}redirect('cart.php');}
$items=[];$subtotal=0;foreach($_SESSION['cart']??[] as $id=>$qty){$q=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1');$q->execute([(int)$id]);if($p=$q->fetch()){$qty=min((int)$qty,(int)$p['stock']);if($qty<1)continue;$price=(float)($p['sale_price']?:$p['price']);$line=$price*$qty;$subtotal+=$line;$items[]=['p'=>$p,'qty'=>$qty,'line'=>$line];}else unset($_SESSION['cart'][$id]);}site_header($pdo,'Shopping bag');$flash=get_flash(); ?>
<section class="page-intro"><span class="eyebrow">YOUR SELECTION</span><h1>Shopping bag</h1></section><section class="section cart-layout"><div><?php if($flash): ?><div class="notice <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif; ?><?php if(!$items): ?><div class="empty-state">Your bag is currently empty. <a href="shop.php">Explore the collection</a></div><?php else: ?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><?php foreach($items as $item):$p=$item['p']; ?><div class="cart-row"><img src="<?=e(product_image($p['image']))?>" alt="<?=e($p['name'])?>"><div><a href="product.php?slug=<?=e($p['slug'])?>"><b><?=e($p['name'])?></b></a><p><?=money((float)($p['sale_price']?:$p['price']))?></p><label>Qty <input type="number" name="qty[<?=$p['id']?>]" min="0" max="<?=$p['stock']?>" value="<?=$item['qty']?>"></label></div><b><?=money($item['line'])?></b><button formaction="cart.php" formmethod="post" name="action" value="remove" onclick="this.form.querySelector('[name=id]').value='<?=$p['id']?>'">Remove</button></div><?php endforeach; ?><input type="hidden" name="id" value=""><button class="button button-outline" type="submit">UPDATE BAG</button></form><?php endif; ?></div><?php if($items): ?><aside class="summary"><h2>Summary</h2><p>Subtotal <b><?=money($subtotal)?></b></p><p>Shipping calculated after checkout.</p><hr><p class="total">Total <b><?=money($subtotal)?></b></p><a class="button full" href="checkout.php">PROCEED TO CHECKOUT</a><a class="text-link" href="shop.php">CONTINUE SHOPPING</a></aside><?php endif; ?></section><?php site_footer($pdo); ?>
